<template>
  <Popover v-model:open="open">
    <PopoverAnchor as="div" class="relative w-full">
      <PopoverTrigger as-child>
        <Button
          variant="outline"
          :class="cn('w-full h-10 justify-start text-left font-normal', !value && 'text-muted-foreground', buttonClass)"
          :prepend-icon="icon"
        >
          {{ value ? formatUTCDateString(value.toString(), 'MM/dd/yyyy') : placeholder }}
        </Button>
      </PopoverTrigger>
      <XIcon
        v-if="value"
        class="h-4 w-4 ml-2 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
        @click.stop.prevent="value = undefined"
      />
    </PopoverAnchor>
    <PopoverContent class="w-auto p-0">
      <CalendarYearMonth
        v-if="isYearMonthCalendar"
        v-model="value"
        initial-focus
        :min-value="minValue"
        :max-value="maxValue"
        :end-year-option="endYearOption"
        @update:model-value="() => (open = false)"
      />
      <Calendar
        v-else
        v-model="value"
        initial-focus
        :min-value="minValue"
        :max-value="maxValue"
        @update:model-value="() => (open = false)"
      />
    </PopoverContent>
  </Popover>
</template>

<script setup lang="ts">
import { cn } from '~/components/ui/utils';
import { type CalendarDate, type DateValue, parseDate } from '@internationalized/date';
import { XIcon } from 'lucide-vue-next';
import { PopoverAnchor } from 'reka-ui';

interface Props {
  placeholder?: string;
  isYearMonthCalendar?: boolean;
  buttonClass?: string;
  minValue?: CalendarDate;
  maxValue?: CalendarDate;
  endYearOption?: CalendarDate;
  icon?: any;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: 'mm/dd/yyyy',
  buttonClass: 'w-full',
  minValue: undefined,
  maxValue: undefined,
  endYearOption: undefined,
  icon: undefined,
});

// The bound value can arrive as an ISO date string (e.g. a vee-validate field whose
// Zod schema casts the date to a string on initial values). The calendar primitives
// require a DateValue, so coerce strings via parseDate while still emitting a DateValue.
const rawValue = defineModel() as Ref<DateValue | string | undefined>;
const value = computed<DateValue | undefined>({
  get() {
    const v = rawValue.value;
    if (!v) return undefined;
    return typeof v === 'string' ? parseDate(v) : v;
  },
  set(newVal) {
    rawValue.value = newVal;
  },
});
const open = defineModel<boolean>('open', { default: false });
</script>

<style scoped lang="scss"></style>
